computation_sql:
SELECT DATE_SUB(W.ModifiedDate, INTERVAL 1 HOUR) AS computed_value, target_table.ActualEndDate AS actual_value
FROM WorkOrderRouting AS target_table
JOIN WorkOrder AS W ON W.WorkOrderID = target_table.WorkOrderID;

SELECT w.StartDate AS computed_value, target_table.ScheduledStartDate AS actual_value
FROM WorkOrderRouting AS target_table
INNER JOIN WorkOrder AS w ON w.WorkOrderID = target_table.WorkOrderID;

SELECT DATE_SUB(w.DueDate, INTERVAL 11 DAY) AS computed_value, target_table.ScheduledStartDate AS actual_value
FROM WorkOrderRouting AS target_table
INNER JOIN WorkOrder AS w ON w.WorkOrderID = target_table.WorkOrderID;

SELECT
  CASE WHEN cs.constructorId IS NOT NULL THEN
    LOWER(
      REPLACE(
        TRIM(
          REGEXP_REPLACE(
            REGEXP_REPLACE(target_table.name, '[^[:alnum:]-]+', ' '),
            '[[:space:]]+', ' '
          )
        ),
        ' ', '_'
      )
    )
  ELSE NULL END AS computed_value,
  target_table.constructorRef AS actual_value
FROM constructors AS target_table
LEFT JOIN (
  SELECT DISTINCT constructorId FROM constructorStandings
) AS cs ON cs.constructorId = target_table.constructorId;

SELECT h.OrderDate AS computed_value, target_table.ModifiedDate AS actual_value
FROM SalesOrderDetail AS target_table
JOIN SalesOrderHeader AS h ON h.SalesOrderID = target_table.SalesOrderID;

SELECT DATE_SUB(h.ModifiedDate, INTERVAL 7 DAY) AS computed_value, target_table.ModifiedDate AS actual_value
FROM SalesOrderDetail AS target_table
JOIN SalesOrderHeader AS h ON h.SalesOrderID = target_table.SalesOrderID;

SELECT DATE_ADD(DATE_SUB(h.ShipDate, INTERVAL 7 DAY), INTERVAL 1 HOUR) AS computed_value, target_table.ModifiedDate AS actual_value
FROM SalesOrderDetail AS target_table
JOIN SalesOrderHeader AS h ON h.SalesOrderID = target_table.SalesOrderID;

SELECT DATE_ADD(DATE_ADD(soh.ShipDate, INTERVAL -7 DAY), INTERVAL 1 HOUR) AS computed_value, target_table.ModifiedDate AS actual_value
FROM SalesOrderHeaderSalesReason AS target_table
JOIN SalesOrderHeader AS soh ON soh.SalesOrderID = target_table.SalesOrderID;

SELECT CAST((target_table.grade >= 3.0) AS SIGNED) AS computed_value,
       target_table.passed AS actual_value
FROM Enrollment AS target_table;

SELECT p.lastName AS computed_value, target_table.last_name AS actual_value
FROM player_allstar AS target_table
LEFT JOIN players AS p ON p.playerID = target_table.playerID;

SELECT lt.time AS computed_value, target_table.fastestLapTime AS actual_value
FROM results AS target_table
LEFT JOIN lapTimes lt ON lt.raceId = target_table.raceId AND lt.driverId = target_table.driverId AND lt.lap = target_table.fastestLap;
